# 45-degree hatch starting 12px down; shortened so it
# stays inside thin platforms.
var hatch: float = minf(7.0, r.size.y - 12.0)
if hatch > 0.0:
    for x in range(int(r.position.x)+12, int(r.end.x), 24):
        draw_line(Vector2(x, r.position.y+12),
                  Vector2(x+hatch, r.position.y+12+hatch),
                  Color("405166"), 1)

var on: float = cycle * float(entry.on_ratio)  # 3.0 * 0.6 = 1.8 s
var t:  float = fmod(elapsed + float(entry.phase), cycle)
return {
    "solid": t < on,
    "warn":  t >= on - 0.5 and t < on,   # the blink
    "left":  maxf(0.0, on - t),
}

var left: float = game.cycle_solid_left(0)
if fail_mode and not deliberate_miss_used:
    # A real jump into a real gap. Nothing is disabled
    # to make it fail.
    if left <= 0.0:
        deliberate_miss_used = true
        return true

for entry in level.hazards:
    var h := Rect2(entry[0], entry[1], entry[2], entry[3])
    for i in range(maxi(1, int(h.size.x / 8.0))):
        var x: float = h.position.x + i*8.0
        draw_colored_polygon(PackedVector2Array([
            Vector2(x,   h.end.y),       # base from the rect
            Vector2(x+4, h.position.y),  # tip  from the rect
            Vector2(x+8, h.end.y)]), Color("d24e42"))
